//! Minimal specs for SANY behaviours, in `tests/sany-cases/`.
//!
//! Each `.tla` file is a one-module spec that pins one behaviour: a
//! precedence range, an associativity rule, a junction-list alignment rule
//! (including SANY's tab and UTF-16 column counting), a `belchDEF` effect,
//! a lexer form, or a proof-structure rule. `verdicts.txt` holds the pinned
//! SANY parser's verdict for each, generated by the oracle (never edited).

use dive_syntax::parse_module;
use std::path::Path;

#[test]
fn every_case_matches_sany() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/sany-cases");
    let verdicts = match std::fs::read_to_string(dir.join("verdicts.txt")) {
        Ok(s) => s,
        Err(e) => unreachable!("cannot read verdicts: {e}"),
    };
    let mut checked = 0;
    let mut failures = Vec::new();
    for line in verdicts.lines().filter(|l| !l.starts_with('#')) {
        let Some((file, verdict)) = line.split_once('\t') else {
            unreachable!("bad line {line:?}")
        };
        let src = match std::fs::read_to_string(dir.join(file)) {
            Ok(s) => s,
            Err(e) => unreachable!("cannot read {file}: {e}"),
        };
        let p = parse_module(&src);
        assert_eq!(p.syntax().to_string(), src, "{file} not lossless");
        let sany_accepts = verdict == "accept";
        if p.is_ok() != sany_accepts {
            failures.push(format!(
                "{file}: SANY {verdict}s, dive {} {:?}",
                if p.is_ok() { "accepts" } else { "rejects" },
                p.diagnostics()
                    .first()
                    .map(|d| (d.code.as_str(), d.message.clone()))
            ));
        }
        checked += 1;
    }
    assert!(checked >= 170, "only {checked} cases");
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn every_case_file_has_a_verdict() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/sany-cases");
    let verdicts = std::fs::read_to_string(dir.join("verdicts.txt")).unwrap_or_default();
    let Ok(entries) = std::fs::read_dir(&dir) else {
        unreachable!("missing {}", dir.display())
    };
    for e in entries.filter_map(Result::ok) {
        let name = e.file_name().to_string_lossy().into_owned();
        if Path::new(&name).extension().is_some_and(|x| x == "tla") {
            assert!(
                verdicts
                    .lines()
                    .any(|l| l.starts_with(&format!("{name}\t"))),
                "{name} has no recorded SANY verdict"
            );
        }
    }
}
